<script>(()=>{const v=document.getElementById('scanner-video'),s=document.getElementById('scanner-status'),stop=document.getElementById('scanner-stop');let stream,timer,busy=false,c=document.createElement('canvas'),g=c.getContext('2d',{willReadFrequently:true});const end=()=>{clearTimeout(timer);stream?.getTracks().forEach(t=>t.stop());};const tick=async()=>{if(!stream||busy)return;if(v.readyState>=2){c.width=Math.min(v.videoWidth,800);c.height=Math.round(v.videoHeight*c.width/v.videoWidth);g.drawImage(v,0,0,c.width,c.height);const q=jsQR(g.getImageData(0,0,c.width,c.height).data,c.width,c.height);if(q){busy=true;end();try{let r=await fetch('{{ route('admin.bpppmnu.events.scan-member',$event) }}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body:JSON.stringify({nuist_id:q.data.trim()})});let d=await r.json();if(!r.ok)throw Error(d.message||'Barcode tidak dikenali');await Swal.fire({icon:'success',title:'Presensi berhasil',text:d.name,confirmButtonColor:'#00553f'});location.reload()}catch(e){s.textContent=e.message;busy=false;start()}}timer=setTimeout(tick,180)};const start=async()=>{try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});v.srcObject=stream;await v.play();s.textContent='Kamera siap. Arahkan ke barcode peserta.';tick()}catch(e){s.textContent='Kamera tidak dapat dibuka. Pastikan izin kamera diberikan.'}};stop.onclick=()=>{end();location.href='{{ route('admin.bpppmnu.events.show',$event) }}'};start()})();</script>
